const char *ldb_errstring(struct ldb_context *ldb) /* <=== ldb_errstring */ 
{
	if (ldb->err_string) {
		return ldb->err_string;
	}

	return NULL;
}

void ldb_asprintf_errstring(struct ldb_context *ldb, const char *format, ...) /* <=== ldb_asprintf_errstring */ 
{
	va_list ap;
	char *old_err_string = NULL;
	if (ldb->err_string) {
		old_err_string = ldb->err_string;
	}

	va_start(ap, format);
	ldb->err_string = talloc_vasprintf(ldb, format, ap);
	va_end(ap);

	TALLOC_FREE(old_err_string);

	if (ldb->flags & LDB_FLG_ENABLE_TRACING) {
		ldb_debug(ldb, LDB_DEBUG_TRACE, "ldb_asprintf/set_errstring: %s",
			  ldb->err_string);
	}
}

int talloc_free(void *ptr) /* <=== talloc_free */ 
{
	return talloc_unlink(talloc_parent(ptr), ptr);
}

int ldb_error_at(struct ldb_context *ldb, int ecode, /* <=== ldb_error_at */ 
		 const char *reason, const char *file, int line)
{
	if (reason == NULL) {
		reason = ldb_strerror(ecode);
	}
	ldb_asprintf_errstring(ldb, "%s at %s:%d", reason, file, line);
	return ecode;
}

